float sy_sqrt(float x) { return x <= 0.f ? 0.f : sy_exp2(0.5f * sy_log2(x)); }

/* y at x by the points (sorted by x), linear (lg = 0) or linear in log(y) (lg = 1); held beyond the ends */
static float interp(const pt *p, int n, float x, int lg)
{
    int i;
    float f;
    if (x <= p[0].x) return p[0].y;
    if (x >= p[n - 1].x) return p[n - 1].y;
    for (i = 1; i < n - 1 && x > p[i].x; i++)
        ;
    f = (x - p[i - 1].x) / (p[i].x - p[i - 1].x);
    if (lg && p[i - 1].y > 0.f && p[i].y > 0.f)
        return FEXP2(FLOG2(p[i - 1].y) + f * (FLOG2(p[i].y) - FLOG2(p[i - 1].y)));
    return p[i - 1].y + f * (p[i].y - p[i - 1].y);
}
